<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Chat temporal | Patitas con Hogar</title><style>:root{--ink:#291117;--red:#a9271d;--cream:#fffaf6;--line:#eadfda}*{box-sizing:border-box}body{margin:0;background:var(--cream);color:var(--ink);font:16px/1.55 system-ui,sans-serif}.wrap{width:min(1000px,calc(100% - 32px));margin:30px auto}.chat{height:min(75vh,720px);min-height:500px;background:white;border:2px solid var(--ink);border-radius:16px;display:flex;flex-direction:column;overflow:hidden}.chat-head{padding:18px 22px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:center}.chat-head h1{font-size:1.3rem;margin:0}.status{font-size:.85rem;color:#537b5a}.messages{flex:1;overflow:auto;padding:20px;display:flex;flex-direction:column;gap:12px}.bubble{max-width:80%;padding:11px 15px;border-radius:16px;background:#f6eeeb;align-self:flex-start;overflow-wrap:anywhere}.bubble.mine{background:#a9271d;color:white;align-self:flex-end}.bubble small{display:block;font-size:.72rem;opacity:.72;margin-top:3px}.empty{color:#7b7b7b;text-align:center;margin:auto}.composer{border-top:1px solid var(--line);padding:14px;display:flex;gap:10px}.composer input{min-width:0;flex:1;padding:12px;border:1px solid #d5cfcc;border-radius:10px;font:inherit}.composer button,.clear{background:var(--red);color:white;border:0;border-radius:9px;padding:11px 18px;font:700 1rem system-ui;cursor:pointer}.clear{background:transparent;color:var(--red);border:1px solid var(--red);padding:7px 10px;font-size:.85rem}.hint{color:#6b625e;font-size:.92rem}.back{color:var(--red);font-weight:700}@media(max-width:560px){.wrap{margin:16px auto}.chat{min-height:65vh}.chat-head{padding:14px}.composer{padding:10px}.composer button{padding:10px}}</style></head><body><?php require __DIR__.'/menu.php'; ?><main class="wrap"><a class="back" href="/Foto/public/index.html">← Volver al inicio</a><h1>Chat temporal de atención</h1><p class="hint">Escríbenos una pregunta. El historial se guarda solo en este navegador durante 24 horas y puedes borrarlo cuando quieras. No incluyas datos sensibles.</p><section class="chat" aria-label="Chat temporal"><header class="chat-head"><h2>🐾 Patitas con Hogar</h2><span class="status">● Disponible</span><button class="clear" id="clear" type="button">Borrar chat</button></header><div class="messages" id="messages" aria-live="polite"></div><form class="composer" id="form"><input id="message" maxlength="500" placeholder="Escribe un mensaje…" aria-label="Escribe un mensaje" required><button>Enviar</button></form></section></main><script>const key='patitas-chat-<?=e($chatId)?>',box=document.getElementById('messages');let history=[];try{const saved=JSON.parse(sessionStorage.getItem(key)||'null');if(saved&&Date.now()-saved.updated<86400000)history=saved.messages||[]}catch{}function draw(){box.replaceChildren();if(!history.length){const p=document.createElement('p');p.className='empty';p.textContent='Aún no hay mensajes. Escribe tu pregunta para iniciar el chat.';box.append(p);return}history.forEach(item=>{const b=document.createElement('div');b.className='bubble'+(item.mine?' mine':'');b.textContent=item.text;const time=document.createElement('small');time.textContent=item.time;b.append(time);box.append(b)});box.scrollTop=box.scrollHeight}function save(){sessionStorage.setItem(key,JSON.stringify({updated:Date.now(),messages:history}));draw()}document.getElementById('form').addEventListener('submit',event=>{event.preventDefault();const field=document.getElementById('message'),text=field.value.trim();if(!text)return;history.push({text,mine:true,time:new Date().toLocaleTimeString('es-MX',{hour:'2-digit',minute:'2-digit'})});field.value='';save()});document.getElementById('clear').addEventListener('click',()=>{if(!confirm('¿Borrar el historial temporal de este chat?'))return;history=[];sessionStorage.removeItem(key);draw()});draw();</script><script src="/Seguir/tracker.js" defer></script></body></html>
